      backup_text =
        "# Seed Catalog #\n\n\
         # The widest API surface in this set, and the only app here that \
         issues real #\n\
         # commands, so its update returns (Model, Cmd) directly rather than \
         through #\n\
         # a noCmd wrapper. #\n\n\
         # Exercises Select, Option, OnChange, OnMouseEnter, OnMouseLeave, #\n\
         # OnDoubleClick, Delay, CopyToClipboard, CmdBatch, SubBatch, \
         OnResize, Ol, A, #\n\
         # Href, Classes and Checked. #\n\n\
         type Action =\n\
         + SelectCategory(String)\n\
         + HoverSeed(Int)\n\
         + UnhoverSeed\n\
         + CollectSeed(Int)\n\
         + DismissNotification\n\
         + ShareCollection\n\
         + WindowResized(Int, Int)\n\
         + ToggleNightMode\n\
         in\n\n\
         type Seed = (\n\
         name = String,\n\
         category = String,\n\
         emoji = String,\n\
         desc = String\n\
         ) in\n\n\
         type Model = (\n\
         category = String,\n\
         hoveredSeed = Int,\n\
         collected = [Int],\n\
         notification = String,\n\
         windowWidth = Int,\n\
         nightMode = Bool\n\
         ) in\n\n\
         let seeds: [Seed] = [\n\
         (name=\"Phantom Orchid\", category=\"Flowers\", \
         emoji=\"\240\159\140\184\", desc=\"Blooms only at midnight\"),\n\
         (name=\"Wraith Basil\", category=\"Herbs\", \
         emoji=\"\240\159\140\191\", desc=\"Season your spectral soups\"),\n\
         (name=\"Ghost Cap\", category=\"Mushrooms\", \
         emoji=\"\240\159\141\132\", desc=\"Glows with eerie light\"),\n\
         (name=\"Banshee Rose\", category=\"Flowers\", \
         emoji=\"\240\159\140\185\", desc=\"Its thorns wail in wind\"),\n\
         (name=\"Spirit Sage\", category=\"Herbs\", \
         emoji=\"\240\159\141\131\", desc=\"Grants visions of beyond\"),\n\
         (name=\"Shade Truffle\", category=\"Mushrooms\", \
         emoji=\"\240\159\140\176\", desc=\"Found in haunted groves\")\n\
         ] in\n\n\
         let empty_ints : [Int] = [] in\n\
         let init: Model = (\n\
         category=\"All\",\n\
         hoveredSeed= -1,\n\
         collected=empty_ints,\n\
         notification=\"\",\n\
         windowWidth=800,\n\
         # Opens in daylight, matching the rest of the examples; the toggle is #\n\
         # the point of the Checked demo #\n\
         nightMode=false\n\
         ) in\n\n\
         let contains(lst: [Int], val: Int): Bool =\n\
         length(filter(lst, fun x -> x == val)) > 0\n\
         in\n\n\
         # Hazel has no record-update syntax, so each field change gets a \
         small named #\n\
         # setter. Without these, every branch of `update` would respell all \
         six #\n\
         # fields and the actual change would be buried. #\n\n\
         let setCategory(model: Model, category: String): Model =\n\
         (\n\
         category = category,\n\
         hoveredSeed = model.hoveredSeed,\n\
         collected = model.collected,\n\
         notification = model.notification,\n\
         windowWidth = model.windowWidth,\n\
         nightMode = model.nightMode\n\
         )\n\
         in\n\n\
         let setHover(model: Model, hoveredSeed: Int): Model =\n\
         (\n\
         category = model.category,\n\
         hoveredSeed = hoveredSeed,\n\
         collected = model.collected,\n\
         notification = model.notification,\n\
         windowWidth = model.windowWidth,\n\
         nightMode = model.nightMode\n\
         )\n\
         in\n\n\
         let setNotification(model: Model, notification: String): Model =\n\
         (\n\
         category = model.category,\n\
         hoveredSeed = model.hoveredSeed,\n\
         collected = model.collected,\n\
         notification = notification,\n\
         windowWidth = model.windowWidth,\n\
         nightMode = model.nightMode\n\
         )\n\
         in\n\n\
         let setWidth(model: Model, windowWidth: Int): Model =\n\
         (\n\
         category = model.category,\n\
         hoveredSeed = model.hoveredSeed,\n\
         collected = model.collected,\n\
         notification = model.notification,\n\
         windowWidth = windowWidth,\n\
         nightMode = model.nightMode\n\
         )\n\
         in\n\n\
         let toggleNight(model: Model): Model =\n\
         (\n\
         category = model.category,\n\
         hoveredSeed = model.hoveredSeed,\n\
         collected = model.collected,\n\
         notification = model.notification,\n\
         windowWidth = model.windowWidth,\n\
         nightMode = !model.nightMode\n\
         )\n\
         in\n\n\
         # Collecting changes two fields at once #\n\
         let collect(model: Model, idx: Int): Model =\n\
         (\n\
         category = model.category,\n\
         hoveredSeed = model.hoveredSeed,\n\
         collected = model.collected @ [idx],\n\
         notification = \"Seed collected!\",\n\
         windowWidth = model.windowWidth,\n\
         nightMode = model.nightMode\n\
         )\n\
         in\n\n\
         let update(model: Model, action: Action): (Model, Cmd) =\n\
         case action\n\
         | SelectCategory(cat) => (setCategory(model, cat), CmdNone)\n\
         | HoverSeed(idx) => (setHover(model, idx), CmdNone)\n\
         | UnhoverSeed => (setHover(model, -1), CmdNone)\n\
         | CollectSeed(idx) =>\n\
         if contains(model.collected, idx)\n\
         then (model, CmdNone)\n\
         else (collect(model, idx), Delay(2000.0, DismissNotification))\n\
         | DismissNotification => (setNotification(model, \"\"), CmdNone)\n\
         | ShareCollection =>\n\
         let count_str = string_of_int(length(model.collected)) in\n\
         let text = \"My ghost garden has \" ++ count_str ++ \" spectral \
         seeds!\" in\n\
         (\n\
         setNotification(model, \"Copied to clipboard!\"),\n\
         CmdBatch([CopyToClipboard(text), Delay(2000.0, DismissNotification)])\n\
         )\n\
         | WindowResized(w, _h) => (setWidth(model, w), CmdNone)\n\
         | ToggleNightMode => (toggleNight(model), CmdNone)\n\
         end\n\
         in\n\n\
         let filtered_seeds(model: Model): [Seed] =\n\
         if model.category == \"All\" then seeds\n\
         else filter(seeds, fun s -> s.category == model.category)\n\
         in\n\n\
         let view(model: Model): HTML =\n\
         # Day is the editor's own paper; night reuses the firefly's sky, so \
         the two #\n\
         # dark things in this example set share one palette #\n\
         let bg = if model.nightMode then \"oklch(21% 0.04 300)\" else \
         \"var(--SAND)\" in\n\
         let fg = if model.nightMode then \"oklch(80% 0.03 300)\" else \
         \"var(--STONE)\" in\n\
         let muted = if model.nightMode then \"oklch(62% 0.03 300)\" else \
         \"var(--BR3)\" in\n\
         let rule = if model.nightMode then \"oklch(38% 0.05 300)\" else \
         \"var(--BR1)\" in\n\
         let accent = if model.nightMode then \"oklch(78% 0.10 300)\" else \
         \"var(--BR4)\" in\n\
         let card_bg = if model.nightMode then \"oklch(26% 0.04 300)\" else \
         \"var(--T1)\" in\n\
         let band_bg = if model.nightMode then \"oklch(25% 0.04 300)\" else \
         \"var(--T2)\" in\n\
         let gold = \"oklch(64% 0.14 90)\" in\n\
         let sidePad = (\"padding\", \"0.7em 1em\") in\n\
         let ruleTop = (\"border-top\", \"1px solid \" ++ rule) in\n\
         let sectionLabel(text: String): HTML =\n\
         Div([Style([(\"font-size\", \"0.75em\"), (\"color\", muted),\n\
         (\"text-transform\", \"uppercase\"), (\"margin-bottom\", \"0.5em\")])],\n\
         [Text(text)])\n\
         in\n\
         Div(\n\
         [\n\
         Id(\"seed-catalog\"),\n\
         Classes([\"catalog-app\", if model.nightMode then \"night-mode\" else \
         \"day-mode\"]),\n\
         Style([\n\
         (\"max-width\", \"460px\"),\n\
         (\"margin\", \"0 auto\"),\n\
         (\"font-family\", \"var(--code-font)\"),\n\
         (\"font-size\", \"0.85em\"),\n\
         (\"background\", bg),\n\
         (\"color\", fg),\n\
         (\"border-radius\", \"0.4em\"),\n\
         (\"border\", \"1px solid \" ++ rule),\n\
         (\"overflow\", \"hidden\")\n\
         ])\n\
         ],\n\
         [\n\
         # Title #\n\
         Div(\n\
         [Style([(\"padding\", \"0.9em 1em 0.8em\"), (\"text-align\", \
         \"center\")])],\n\
         [\n\
         Div([Style([(\"font-size\", \"1.2em\"), (\"font-weight\", \"bold\"), \
         (\"color\", accent)])],\n\
         [Text(\"Spectral Seed Catalog\")]),\n\
         Div([Style([(\"font-size\", \"0.75em\"), (\"color\", muted), \
         (\"margin-top\", \"0.3em\")])],\n\
         [Text(\"A late night ghost gardener's companion\")])\n\
         ]\n\
         ),\n\n\
         # Night mode toggle with Checked, and the archive link #\n\
         Div(\n\
         [Style([sidePad, (\"background\", band_bg), ruleTop,\n\
         (\"border-bottom\", \"1px solid \" ++ rule),\n\
         (\"display\", \"flex\"), (\"justify-content\", \"space-between\"),\n\
         (\"align-items\", \"center\"), (\"gap\", \"0.5em\")])],\n\
         [\n\
         A(\n\
         [Href(\"#ghostly-gardens\"),\n\
         Style([(\"color\", accent), (\"text-decoration\", \"none\"), \
         (\"font-size\", \"0.75em\")])],\n\
         [Text(\"Ghostly Gardens Archives\")]\n\
         ),\n\
         Label([Style([(\"font-size\", \"0.75em\"), (\"color\", muted), \
         (\"cursor\", \"pointer\"),\n\
         (\"white-space\", \"nowrap\")])], [\n\
         Input([\n\
         Type(\"checkbox\"),\n\
         Checked(model.nightMode),\n\
         OnClick(ToggleNightMode)\n\
         ]),\n\
         Text(\" Night Mode\")\n\
         ])\n\
         ]\n\
         ),\n\n\
         # Category filter with Select and OnChange #\n\
         Div(\n\
         [Style([sidePad])],\n\
         [\n\
         sectionLabel(\"Filter by Category\"),\n\
         Select(\n\
         [\n\
         OnChange(fun value -> SelectCategory(value)),\n\
         Style([\n\
         (\"width\", \"100%\"),\n\
         (\"padding\", \"0.35em 0.5em\"),\n\
         (\"font-family\", \"inherit\"),\n\
         (\"font-size\", \"0.85em\"),\n\
         (\"border-radius\", \"3px\"),\n\
         (\"border\", \"1px solid \" ++ rule),\n\
         (\"background\", card_bg),\n\
         (\"color\", fg)\n\
         ])\n\
         ],\n\
         [\n\
         Option([Value(\"All\"), Selected(model.category == \"All\")], \"All \
         Seeds\"),\n\
         Option([Value(\"Flowers\"), Selected(model.category == \"Flowers\")], \
         \"Flowers\"),\n\
         Option([Value(\"Herbs\"), Selected(model.category == \"Herbs\")], \
         \"Herbs\"),\n\
         Option([Value(\"Mushrooms\"), Selected(model.category == \
         \"Mushrooms\")], \"Mushrooms\")\n\
         ]\n\
         )\n\
         ]\n\
         ),\n\n\
         # Notification banner #\n\
         if model.notification != \"\" then\n\
         Div(\n\
         [Style([\n\
         sidePad,\n\
         (\"background\", \"var(--G0)\"),\n\
         (\"color\", \"var(--SAND)\"),\n\
         (\"font-size\", \"0.75em\"),\n\
         (\"text-align\", \"center\")\n\
         ])],\n\
         [Text(model.notification)]\n\
         )\n\
         else Div([], []),\n\n\
         # Seed cards with OnMouseEnter, OnMouseLeave, OnDoubleClick #\n\
         Div(\n\
         [Style([sidePad, ruleTop])],\n\
         [\n\
         sectionLabel(\"Seeds (\" ++ \
         string_of_int(length(filtered_seeds(model))) ++ \")\"),\n\
         Div(\n\
         [Style([\n\
         (\"display\", \"grid\"),\n\
         # auto-fit tracks the card's own width, so this lays out correctly #\n\
         # both docked in the sidebar and undocked inline #\n\
         (\"grid-template-columns\", \"repeat(auto-fit, minmax(200px, 1fr))\"),\n\
         (\"gap\", \"0.4em\")\n\
         ])],\n\
         mapi(seeds, (fun (idx, seed) ->\n\
         if model.category == \"All\" || seed.category == model.category then\n\
         Div(\n\
         [\n\
         Classes([\"seed-card\", seed.category]),\n\
         OnMouseEnter(HoverSeed(idx)),\n\
         OnMouseLeave(UnhoverSeed),\n\
         OnDoubleClick(CollectSeed(idx)),\n\
         Style([\n\
         (\"padding\", \"0.5em 0.6em\"),\n\
         # Border width is constant so collecting never reflows the grid #\n\
         (\"border\", \"1px solid \" ++ (if contains(model.collected, idx) \
         then gold else rule)),\n\
         (\"border-radius\", \"3px\"),\n\
         (\"background\", if model.hoveredSeed == idx then band_bg else \
         card_bg),\n\
         (\"cursor\", \"pointer\"),\n\
         (\"transition\", \"background 0.2s, border-color 0.2s\")\n\
         ])\n\
         ],\n\
         [\n\
         Div(\n\
         [Style([(\"display\", \"flex\"), (\"justify-content\", \
         \"space-between\"),\n\
         (\"align-items\", \"baseline\"), (\"gap\", \"0.4em\")])],\n\
         [\n\
         Span(\n\
         [Style([(\"font-weight\", \"bold\")])],\n\
         [Text(seed.emoji ++ \" \" ++ seed.name)]\n\
         ),\n\
         Span(\n\
         [Style([(\"font-size\", \"0.75em\"), (\"color\", muted)])],\n\
         [Text(seed.category)]\n\
         )\n\
         ]\n\
         ),\n\
         # Always rendered, so revealing it on hover doesn't move the card #\n\
         Div(\n\
         [Style([\n\
         (\"margin-top\", \"0.3em\"),\n\
         (\"font-size\", \"0.75em\"),\n\
         (\"color\", muted),\n\
         (\"opacity\", if model.hoveredSeed == idx then \"1\" else \"0\"),\n\
         (\"transition\", \"opacity 0.2s\")\n\
         ])],\n\
         [Text(seed.desc)]\n\
         ),\n\
         Div(\n\
         [Style([(\"font-size\", \"0.75em\"), (\"margin-top\", \"0.3em\"),\n\
         (\"color\", if contains(model.collected, idx) then gold else muted)])],\n\
         [Text(if contains(model.collected, idx)\n\
         then \"Collected\"\n\
         else \"Double-click to collect\")]\n\
         )\n\
         ]\n\
         )\n\
         else Div([Style([(\"display\", \"none\")])], [])\n\
         ))\n\
         )\n\
         ]\n\
         ),\n\n\
         # Collected seeds with Ol #\n\
         Div(\n\
         [Style([sidePad, ruleTop])],\n\
         [\n\
         sectionLabel(\"Your Collection (\" ++ \
         string_of_int(length(model.collected)) ++ \")\"),\n\
         if length(model.collected) > 0 then\n\
         Div([], [\n\
         Ol(\n\
         [Style([(\"padding-left\", \"1.2em\"), (\"margin\", \"0\")])],\n\
         map(model.collected, fun idx ->\n\
         Li([], [Text(nth(seeds, idx).name)])\n\
         )\n\
         ),\n\
         # Share button with CopyToClipboard #\n\
         Button(\n\
         [\n\
         OnClick(ShareCollection),\n\
         Classes([\"share-btn\"]),\n\
         Style([\n\
         (\"width\", \"100%\"),\n\
         (\"margin-top\", \"0.5em\"),\n\
         (\"padding\", \"0.4em\"),\n\
         (\"background\", \"var(--G0)\"),\n\
         (\"color\", \"var(--SAND)\"),\n\
         (\"border\", \"1px solid var(--G0)\"),\n\
         (\"border-radius\", \"3px\"),\n\
         (\"cursor\", \"pointer\"),\n\
         (\"font-family\", \"inherit\"),\n\
         (\"font-size\", \"0.85em\")\n\
         ])\n\
         ],\n\
         [Text(\"Share Collection\")]\n\
         )\n\
         ])\n\
         else\n\
         Div(\n\
         [Style([(\"color\", muted), (\"font-size\", \"0.75em\")])],\n\
         [Text(\"Nothing collected yet \226\128\148 double-click a seed to add \
         it\")]\n\
         )\n\
         ]\n\
         ),\n\n\
         # Footer with window width, kept live by OnResize #\n\
         Div(\n\
         [Style([(\"padding\", \"0.6em 1em\"), (\"text-align\", \"center\"),\n\
         (\"font-size\", \"0.75em\"), (\"color\", muted), ruleTop])],\n\
         [Text(\"window \" ++ string_of_int(model.windowWidth) ++ \"px\")]\n\
         )\n\
         ]\n\
         )\n\
         in\n\n\
         let subs(_model: Model): Sub =\n\
         SubBatch([\n\
         OnResize(fun (w, h) -> WindowResized(w, h))\n\
         ])\n\
         in\n\n\
         # Tests #\n\n\
         hint \"choosing a category filters the catalog\"\n\
         test\n\
         let (m, _) = update(init, SelectCategory(\"Flowers\")) in\n\
         m.category == \"Flowers\"\n\
         && length(filtered_seeds(m)) == 2\n\
         && length(filtered_seeds(init)) == 6\n\
         end;\n\n\
         hint \"hovering marks a seed, leaving clears the mark\"\n\
         test\n\
         let (hovered, _) = update(init, HoverSeed(2)) in\n\
         let (left, _) = update(hovered, UnhoverSeed) in\n\
         hovered.hoveredSeed == 2 && left.hoveredSeed == -1\n\
         end;\n\n\
         hint \"a seed is collected once, and says so until dismissed\"\n\
         test\n\
         let (one, _) = update(init, CollectSeed(0)) in\n\
         let (again, _) = update(one, CollectSeed(0)) in\n\
         let (quiet, _) = update(again, DismissNotification) in\n\
         one.collected == [0]\n\
         && one.notification == \"Seed collected!\"\n\
         && again.collected == [0]\n\
         && quiet.notification == \"\"\n\
         end;\n\n\
         hint \"collecting several seeds keeps them in order\"\n\
         test\n\
         let (m1, _) = update(init, CollectSeed(1)) in\n\
         let (m2, _) = update(m1, CollectSeed(4)) in\n\
         m2.collected == [1, 4]\n\
         end;\n\n\
         hint \"sharing the collection reports back\"\n\
         test\n\
         let (m, _) = update(init, ShareCollection) in\n\
         m.notification == \"Copied to clipboard!\"\n\
         end;\n\n\
         hint \"night mode toggles, and a resize is recorded\"\n\
         test\n\
         let (flipped, _) = update(init, ToggleNightMode) in\n\
         let (back, _) = update(flipped, ToggleNightMode) in\n\
         let (wide, _) = update(init, WindowResized(1024, 768)) in\n\
         # Stated against init rather than a literal, so changing which mode \
         the #\n\
         # catalog opens in can't break this #\n\
         flipped.nightMode == !init.nightMode\n\
         && back.nightMode == init.nightMode\n\
         && wide.windowWidth == 1024\n\
         end;\n\n\
         ^^html((init, update, view, subs))\n";
      refractors = "()";
    } )
